import { useAuth } from "../auth/AuthContext";
import { useEffect, useState } from "react";

export default function Dashboard() {
  const { user } = useAuth();
  const [students, setStudents] = useState([]);

  useEffect(() => {
    if (user?.role === "teacher") {
      fetch(`http://localhost:3001/students?teacher=${user.username}`)
        .then((res) => res.json())
        .then((data) => setStudents(data))
        .catch((err) =>
          console.error("Fehler beim Laden der Schülerdaten:", err)
        );
    }
  }, [user]);

  return (
    <div>
      <h1 className="text-2xl font-bold mb-4 heading-style">Lehrer-Dashboard</h1>

      <table className="table-auto border border-white w-full text-sm text-style">
        <thead>
          <tr>
            <th className="border px-2 py-1">Benutzername</th>
            <th className="border px-2 py-1">Level 1</th>
            <th className="border px-2 py-1">Level 2</th>
            <th className="border px-2 py-1">Level 3</th>
          </tr>
        </thead>
        <tbody>
          {students.map((s, i) => (
            <tr key={i}>
              <td className="border px-2 py-1">{s.username}</td>
              <td className="border px-2 py-1">{s.progress.level1Passed ? "✅" : "❌"}</td>
              <td className="border px-2 py-1">{s.progress.level2Passed ? "✅" : "❌"}</td>
              <td className="border px-2 py-1">{s.progress.level3Passed ? "✅" : "❌"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
